// Auto-generated. Real Barlow (identical to source PDF) + Inter-Thin (Helvetica Neue match), subset to Latin.
/* eslint-disable */
export const FONT_BARLOW_R = "";
export const FONT_BARLOW_SB = "";
export const FONT_NAME = "";

let loaded: Promise<void> | null = null;
export function ensureFonts(): Promise<void> {
  if (loaded) return loaded;
  const defs: [string, string, string][] = [
    ['BarlowR', FONT_BARLOW_R, '400'],
    ['BarlowSB', FONT_BARLOW_SB, '600'],
    ['IDName', FONT_NAME, '200'],
  ];
  loaded = Promise.all(
    defs.map(([fam, b64, wght]) => {
      const ff = new FontFace(fam, 'url(data:font/woff2;base64,' + b64 + ')', { weight: wght });
      return ff.load().then((f) => { (document as any).fonts.add(f); });
    })
  ).then(() => (document as any).fonts.ready).then(() => {});
  return loaded;
}
